function extractJson(value) {
  if (typeof value === 'object' && value !== null) {
    return value;
  }

  if (!value) {
    throw new Error("Réponse vide de l'agent rapport");
  }

  let text = String(value)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  if (text.startsWith('"') && text.endsWith('"')) {
    try {
      text = JSON.parse(text);
    } catch (e) {}
  }

  text = String(text)
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"')
    .trim();

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');

  if (start === -1 || end === -1 || end <= start) {
    throw new Error("Aucun objet JSON trouvé dans la réponse : " + text.slice(0, 500));
  }

  const jsonText = text.slice(start, end + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      "JSON invalide généré par l'agent rapport : " +
      error.message +
      "\n\nExtrait :\n" +
      jsonText.slice(0, 800)
    );
  }
}

const raw = $json.output ?? $json.text ?? $json.response ?? $json;

let rapport = extractJson(raw);

if (rapport.rapport) {
  rapport = rapport.rapport;
}

// Normalisation des clés obligatoires
rapport.titre = rapport.titre ?? rapport.title ?? "Rapport d’empreinte carbone";

rapport.resume_executif =
  rapport.resume_executif ??
  rapport.resume ??
  rapport.résumé ??
  rapport.resumeExecutive ??
  rapport.synthese ??
  "";

rapport.analyse_globale =
  rapport.analyse_globale ??
  rapport.analyse ??
  rapport.analyse_generale ??
  rapport.commentaire_global ??
  "";

rapport.conclusion =
  rapport.conclusion ??
  rapport.conclusion_generale ??
  rapport.synthese_finale ??
  rapport.bilan ??
  "";

rapport.informations_entreprise =
  rapport.informations_entreprise ??
  rapport.entreprise ??
  {};

rapport.resultats_principaux =
  rapport.resultats_principaux ??
  rapport.resultats ??
  {};

rapport.analyse_par_categorie =
  Array.isArray(rapport.analyse_par_categorie)
    ? rapport.analyse_par_categorie
    : [];

rapport.points_critiques =
  Array.isArray(rapport.points_critiques)
    ? rapport.points_critiques
    : [];

rapport.recommandations_generales =
  Array.isArray(rapport.recommandations_generales)
    ? rapport.recommandations_generales
    : [];
rapport.points_critiques = Array.isArray(rapport.points_critiques)
  ? rapport.points_critiques.map(point => {
      if (typeof point === 'string') {
        return point;
      }

      if (point.commentaire) {
        return point.commentaire;
      }

      if (point.categorie && point.emissions_tco2e) {
        return `La catégorie ${point.categorie} représente un point critique avec ${point.emissions_tco2e} tCO2e.`;
      }

      return JSON.stringify(point);
    })
  : [];

rapport.recommandations_generales = Array.isArray(rapport.recommandations_generales)
  ? rapport.recommandations_generales.map(recommandation => {
      if (typeof recommandation === 'string') {
        return recommandation;
      }

      if (recommandation.action_proposee) {
        return recommandation.action_proposee;
      }

      if (recommandation.commentaire) {
        return recommandation.commentaire;
      }

      return JSON.stringify(recommandation);
    })
  : [];
function normalizeTextList(list) {
  if (!Array.isArray(list)) {
    return [];
  }

  return list.map(item => {
    // Cas 1 : déjà une phrase simple
    if (typeof item === 'string') {
      // Si c’est une chaîne JSON du type {"point":"..."}
      const trimmed = item.trim();

      if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
        try {
          const parsed = JSON.parse(trimmed);
          return parsed.point
            ?? parsed.commentaire
            ?? parsed.action_proposee
            ?? parsed.recommandation
            ?? JSON.stringify(parsed);
        } catch (e) {
          return item;
        }
      }

      return item;
    }

    // Cas 2 : objet JSON
    if (typeof item === 'object' && item !== null) {
      return item.point
        ?? item.commentaire
        ?? item.action_proposee
        ?? item.recommandation
        ?? item.description
        ?? JSON.stringify(item);
    }

    return String(item);
  });
}

rapport.points_critiques = normalizeTextList(rapport.points_critiques);
rapport.recommandations_generales = normalizeTextList(rapport.recommandations_generales);
return [
  {
    json: {
      rapport,
      debug_keys: Object.keys(rapport)
    }
  }
];

const rapport = $('parser rapport').item.json.rapport;
const verification = $('vérification rapport code').item.json;

return [
  {
    json: {
      success: true,
      statut: "rapport_genere",
      message: "Rapport généré avec succès",
      rapport,
      verification
    }
  }
];

const verification = $('vérification rapport code').item.json;

return [
  {
    json: {
      success: false,
      statut: "a_regenerer",
      message: "Le rapport doit être régénéré",
      verification,
      erreurs: verification.erreurs || []
    }
  }
];

const donnees = $('Préparer les données rapport').item.json ?? {};
const rapport = $('parser rapport').item.json.rapport ?? {};

const erreurs = [];

function isEmpty(value) {
  return value === undefined || value === null || String(value).trim() === '';
}

if (isEmpty(rapport.titre)) {
  erreurs.push("Le rapport ne contient pas de titre.");
}

if (isEmpty(rapport.resume_executif)) {
  erreurs.push("Le rapport ne contient pas de résumé exécutif.");
}

if (!rapport.informations_entreprise || typeof rapport.informations_entreprise !== 'object') {
  erreurs.push("Le rapport ne contient pas les informations de l’entreprise.");
}

if (!rapport.resultats_principaux || typeof rapport.resultats_principaux !== 'object') {
  erreurs.push("Le rapport ne contient pas les résultats principaux.");
}

if (isEmpty(rapport.analyse_globale)) {
  erreurs.push("Le rapport ne contient pas d’analyse globale.");
}

if (!Array.isArray(rapport.analyse_par_categorie)) {
  erreurs.push("Le rapport ne contient pas d’analyse par catégorie.");
}

if (!Array.isArray(rapport.points_critiques)) {
  erreurs.push("Le rapport ne contient pas de points critiques.");
}

if (!Array.isArray(rapport.recommandations_generales)) {
  erreurs.push("Le rapport ne contient pas de recommandations générales.");
}

if (isEmpty(rapport.conclusion)) {
  erreurs.push("Le rapport ne contient pas de conclusion.");
}

const texte = JSON.stringify(rapport).toLowerCase();

if (texte.includes('tva')) {
  erreurs.push("Le rapport ne doit pas contenir de TVA carbone.");
}

if (texte.includes('tnd')) {
  erreurs.push("Le rapport ne doit pas contenir de montant TND.");
}

const resultats = donnees.resultats ?? donnees.resultat_carbone ?? {};

const totalKgLaravel =
  resultats.total_kgco2e ??
  resultats.total_kg_co2e ??
  resultats.total_kg_co2e_an ??
  null;

const totalTLaravel =
  resultats.total_tco2e ??
  resultats.total_t_co2e_an ??
  null;

const totalKgRapport =
  rapport.resultats_principaux?.total_kgco2e ??
  rapport.resultats_principaux?.total_kg_co2e ??
  null;

const totalTRapport =
  rapport.resultats_principaux?.total_tco2e ??
  rapport.resultats_principaux?.total_t_co2e_an ??
  null;

function equalNumber(a, b) {
  if (a === null || b === null || a === undefined || b === undefined) {
    return true;
  }

  return Math.abs(Number(a) - Number(b)) < 0.001;
}

if (!equalNumber(totalKgLaravel, totalKgRapport)) {
  erreurs.push("Le total kgCO2e du rapport ne correspond pas au total fourni par Laravel.");
}

if (!equalNumber(totalTLaravel, totalTRapport)) {
  erreurs.push("Le total tCO2e du rapport ne correspond pas au total fourni par Laravel.");
}

return [
  {
    json: {
      valide: erreurs.length === 0,
      statut: erreurs.length === 0 ? "valide" : "a_regenerer",
      erreurs,
      message: erreurs.length === 0 ? "Rapport valide" : "Le rapport doit être régénéré",
      debug_keys: Object.keys(rapport)
    }
  }
];

const input = $json.body ?? $json;

const resultats = input.resultats ?? input.resultat_carbone ?? {};
const entreprise = input.entreprise ?? {};
const details = input.details_resultat ?? resultats.details ?? [];

return [
  {
    json: {
      entreprise_id: input.entreprise_id ?? input.entreprise?.id ?? null,
      resultat_id: input.resultat_id ?? input.resultat_carbone_id ?? null,

      entreprise: {
        nom: entreprise.nom ?? null,
        secteur: entreprise.secteur ?? null,
        pays: entreprise.pays ?? null,
        ville: entreprise.ville ?? null,
        nombre_employes: entreprise.nombre_employes ?? null,
        type_production: entreprise.type_production ?? null,
        annee_calcul: entreprise.annee_calcul ?? null
      },

      resultats: {
        total_kgco2e: Number(
          resultats.total_kgco2e ??
          resultats.total_kg_co2e ??
          resultats.total_kg_co2e_an ??
          0
        ),
        total_tco2e: Number(
          resultats.total_tco2e ??
          resultats.total_t_co2e_an ??
          0
        ),
        categorie_dominante: resultats.categorie_dominante ?? null,
        facteur_dominant: resultats.facteur_dominant ?? null
      },

      details_resultat: details
    }
  }
];
